const results = {};
for (const id of ["1:23", "1:26", "13:3", "13:9", "13:31"]) {
  const n = await figma.getNodeByIdAsync(id);
  if (n) {
    results[id] = {
      name: n.name,
      type: n.type,
      width: "width" in n ? n.width : null,
      height: "height" in n ? n.height : null,
      key: "key" in n ? n.key : null,
      componentId: "componentId" in n ? n.componentId : null,
    };
    if ("children" in n) {
      results[id].children = n.children.map(c => {
        const o = { name: c.name, type: c.type };
        if ("width" in c) o.w = Math.round(c.width);
        if ("height" in c) o.h = Math.round(c.height);
        if ("fills" in c && Array.isArray(c.fills)) o.fills = JSON.stringify(c.fills).slice(0, 200);
        if ("strokes" in c && Array.isArray(c.strokes)) o.strokes = JSON.stringify(c.strokes).slice(0, 150);
        if (c.type === "TEXT") { o.chars = c.characters.slice(0, 60); o.font = c.fontName; }
        return o;
      });
    }
  } else {
    results[id] = "NOT FOUND";
  }
}
return JSON.stringify(results, null, 1);

