const page = await figma.getNodeByIdAsync("0:1");
const lines = [];
async function walk(node, depth){
  if (node.type === "TEXT"){
    lines.push(node.characters.replace(/\n/g," ⏎ "));
    return;
  }
  if ("children" in node){
    for (const c of node.children) await walk(c, depth+1);
  }
}
for (const c of page.children) await walk(c, 0);
return lines.join("\n");

