function hex(h,o){const n=parseInt(h,16);return {type:"SOLID",color:{r:((n>>16)&255)/255,g:((n>>8)&255)/255,b:(n&255)/255},opacity:o===undefined?1:o};}
function txt(chars,style,size,colorHex,opts={}){const t=figma.createText();t.fontName={family:"Poppins",style};t.characters=chars;t.fontSize=size;t.fills=[hex(colorHex)];if(opts.ls!==undefined)t.letterSpacing={unit:"PIXELS",value:opts.ls};if(opts.lh)t.lineHeight={unit:"PIXELS",value:opts.lh};if(opts.deco)t.textDecoration=opts.deco;if(opts.w){t.textAutoResize="HEIGHT";t.resize(opts.w,t.height);}if(opts.align)t.textAlignHorizontal=opts.align;return t;}
function autolayout(name,dir,gap,pT,pR,pB,pL,parent){const f=figma.createFrame();f.name=name;f.layoutMode=dir;f.itemSpacing=gap;f.paddingTop=pT;f.paddingRight=pR;f.paddingBottom=pB;f.paddingLeft=pL;f.primaryAxisSizingMode="AUTO";f.counterAxisSizingMode="AUTO";f.fills=[];if(parent)parent.appendChild(f);return f;}
function frame(name,w,h,parent,x,y){const f=figma.createFrame();f.name=name;if(w)f.resize(w,h);if(parent)parent.appendChild(f);if(x!==undefined)f.x=x;if(y!==undefined)f.y=y;return f;}
async function comp(id){return (await figma.getNodeByIdAsync(id)).createInstance();}
async function icon(id,size,colorHex,parent,name){const c=await figma.getNodeByIdAsync(id);const i=c.createInstance();i.resize(size,size*(c.height/c.width));i.name=name;if(colorHex){for(const d of i.findAll(n=>["VECTOR","BOOLEAN_OPERATION","TEXT","RECTANGLE"].includes(n.type))){if("fills" in d){try{d.fills=[hex(colorHex)];}catch(e){}}}}if(parent)parent.appendChild(i);return i;}
